/// <summary>
/// UPSPricingAttribute of table <c>EcoResProduct</c> field SearchName.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeEcoResProductSearchName extends UPSPricingAttributeEcoResProduct implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(EcoResProduct, SearchName);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResProduct ecoResProduct;

    while select SearchName from ecoResProduct
    {
        if (!ret.in(ecoResProduct.SearchName))
        {
            ret.add(ecoResProduct.SearchName);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProduct, SearchName));
    qbr.value(queryValue(_value));
}
